arguments.command:
cd '/filesystem' || exit 1
cd /filesystem && python3 - <<'EOF'
import openpyxl, glob
for f in glob.glob('Equipment/PXA-2024-0002*'):
    print('='*20, f)
    wb=openpyxl.load_workbook(f, data_only=False)
    print('sheets:', wb.sheetnames)
    for ws in wb.worksheets:
        print('---', ws.title, ws.max_row, ws.max_column)
        for row in ws.iter_rows():
            vals=[str(c.value) for c in row if c.value is not None]
            if vals: print(' | '.join(vals))
EOF

cd '/filesystem' || exit 1
cd /filesystem && python3 - <<'EOF'
import openpyxl, glob
for f in glob.glob('Equipment/PXA-2024-0002*'):
    print('='*20, f)
    wb=openpyxl.load_workbook(f)
    for ws in wb.worksheets:
        print('---', ws.title)
        for row in ws.iter_rows():
            for c in row:
                if c.comment: print('COMMENT', c.coordinate, c.comment.text)
        if ws._images: print('images', len(ws._images))
        print('hidden rows', [r for r,d in ws.row_dimensions.items() if d.hidden])
        print('hidden cols', [c for c,d in ws.column_dimensions.items() if d.hidden])
EOF

