# corpus text
corpus=[]
for dp,_,fs in os.walk('/tmp/ahpele/corpus'):
    for f in fs:
        if f.endswith('.txt'):
            corpus.append(open(os.path.join(dp,f),encoding='utf-8',errors='replace').read())
blob=re.sub(r'(?<=\d),(?=\d{3})','',' '.join(corpus))
un=[]
for n in sorted(set(nums), key=lambda x:(len(x),x)):
    variants={n,n.replace(',','')}
    if n.endswith('.0'): variants.add(n[:-2])
    if not any(v in blob for v in variants):
        un.append(n)
print('Unique numbers in letter:',len(set(nums)))
print('Numbers not literally found in any corpus doc:',un)
# Show contexts for unaccounted
for n in un:
    for line in text.split('\n'):
        if n in line:
            print(n,'=>',line[:200])
            break
EOF

